  function frame(now){const dt=Math.min(60,now-lastTime||16);lastTime=now;gameTime=now;const up=keys.has('w')||keys.has('arrowup'),down=keys.has('s')||keys.has('arrowdown'),left=keys.has('a')||keys.has('arrowleft'),right=keys.has('d')||keys.has('arrowright');if(now-stepTimer>135&&(up||down||left||right)){let dx=(right?1:0)-(left?1:0),dy=(down?1:0)-(up?1:0);if(dx&&dy){dx*=.707;dy*=.707}move(dx*.48,dy*.48);stepTimer=now}player.moving=now-stepTimer<100;if(playerAttack>0)playerAttack=Math.max(0,playerAttack-dt/600);if(magicFlash>0)magicFlash=Math.max(0,magicFlash-dt/700);if(damageFlash>0)damageFlash=Math.max(0,damageFlash-dt/300);
    for(const m of wolves){if(!m.alive)continue;m.flash=Math.max(0,m.flash-dt/200);m.attack-=dt/1000;const dist=distance(player,m);if(dist<5&&dist>1.15){m.roam+=dt;if(m.roam>520){const dx=(player.x-m.x)/dist,dy=(player.y-m.y)/dist,nx=m.x+dx*.016*dt,ny=m.y+dy*.016*dt;if(tileType(Math.round(nx),Math.round(ny))!=='water'){m.x=nx;m.y=ny}m.roam=0}}if(dist<=1.35&&m.attack<=0){m.attack=1.65;playerHit()}}
