  updateInventory();updateStats();resize();requestAnimationFrame(frame);
  const clock=document.getElementById('clock');setInterval(()=>{const d=new Date();clock.textContent=d.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})},30000);
})();

